const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Polygon(
    [[[-84.41, 30.22],
      [-84.41, 30.30],
      [-84.30, 30.30],
      [-84.30, 30.22]]], null, false);

  const startEarlyApril = '2004-04-01';
  const endEarlyApril = '2004-04-15';
  const startLateApril = '2004-04-16';
  const endLateApril = '2004-04-30';

  // Landsat 5 SR bands: B3(Red), B4(NIR), B7(SWIR2) for NBR
  const NBR_BANDS = ['B4', 'B7']; // NIR, SWIR2

  // Function to mask clouds and calculate NBR for Landsat 5 SR
  const maskCloudsAndCalcNBR = (image) => {
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    // Get the pixel QA band.
    const qa = image.select('pixel_qa');
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
      .and(qa.bitwiseAnd(cloudsBitMask).eq(0));

    const NBR = image.normalizedDifference(NBR_BANDS).rename('NBR');

    return image.updateMask(mask).select(NBR_BANDS).addBands(NBR);
  };

  // Define NBR threshold for burn scar detection
  // A lower NBR value generally indicates a more severely burned area.
  // We'll consider pixels with NBR < 0.2 as potentially burned.
  const NBR_BURN_THRESHOLD = 0.2;

  // Function to get burn area
  const getBurnArea = (collection, date_start, date_end, periodName) => {
    let col = ee.ImageCollection('LANDSAT/LT05/C01/SR')
      .filterBounds(geometry)
      .filterDate(date_start, date_end)
      .map(maskCloudsAndCalcNBR);

    const colSize = col.size().getInfo();
    if (colSize === 0) {
      console.log(`${periodName} Images: 0`);
      return { collection: col, image: null, area: null, count: 0 };
    }

    // Mosaic images in the collection to get a single image for the period
    const mosaic = col.median().clip(geometry);

    // Calculate valid pixel count for the mosaic
    const validPixelsCount = mosaic.select('NBR').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 30, // Landsat resolution
      maxPixels: 1e9
    }).get('NBR').getInfo();

    if (validPixelsCount === 0) {
      console.log(`${periodName} Images: ${colSize} (Val: 0)`);
      return { collection: col, image: null, area: null, count: 0 };
    }

    // Classify burn scars: NBR < threshold
    const burnScar = mosaic.select('NBR').lt(NBR_BURN_THRESHOLD);

    // Calculate burn scar area in square meters
    const burnAreaStats = burnScar.multiply(ee.Image.pixelArea()).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 30,
      maxPixels: 1e9
    });

    const area = burnAreaStats.get('NBR').getInfo();
    console.log(`${periodName} Images: ${colSize} (Val: ${validPixelsCount})`);

    return { collection: col, image: mosaic, area: area, count: validPixelsCount };
  };

  // 2. Data Acquisition & Check for Early April
  const resultEarlyApril = getBurnArea(
    null, startEarlyApril, endEarlyApril, "Early April");

  // 3. Data Acquisition & Check for Late April
  const resultLateApril = getBurnArea(
    null, startLateApril, endLateApril, "Late April");

  if (resultEarlyApril.area === null || resultLateApril.area === null) {
    if (resultEarlyApril.count === 0 || resultLateApril.count === 0) {
      console.log("C2: No valid pixels for one or both periods after cloud masking.");
      console.log("C2");
      return;
    }
    console.log("C3: Calculation failure (area is null).");
    console.log("C3");
    return;
  }

  // Convert area to square kilometers for readability
  const areaEarlyAprilSqKm = resultEarlyApril.area / 1e6;
  const areaLateAprilSqKm = resultLateApril.area / 1e6;

  console.log(`Early April Burn Area: ${areaEarlyAprilSqKm.toFixed(2)} sq km`);
  console.log(`Late April Burn Area: ${areaLateAprilSqKm.toFixed(2)} sq km`);

  // 5. Validation & Final Answer
  if (areaLateAprilSqKm > areaEarlyAprilSqKm) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
